// Des: Tests cloud flow: failover, sticky choice, alerts, dry purge
// Flo: three mock clouds as vendors b2zz r2zz tigr / turs neon > queue files and records > run the flow > assert where data landed and what failover remembers
// I/O: mock clouds + temp db + temp raw files > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const flow = @import("ru-clou-flow.zig"); const sync = @import("sy-clou-sync.zig"); const cmok = @import("sy-clou-mock.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig"); const pack = @import("ru-purg-pack.zig"); const fail = @import("ru-fail-over.zig"); const civi = @import("ut-date-civi.zig");
const allo = std.testing.allocator;
const NOWZ: i64 = 1795528470301;
const DAYZ: i64 = 86400000;
const BIGG: u64 = 1 << 30;
const Rigg = struct { tmpz: std.testing.TmpDir, c1zz: cmok.Mock, c2zz: cmok.Mock, c3zz: cmok.Mock, dirz: []u8, rawd: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, stos: [3]flow.Vend, sqls: [2]flow.Vsqd, flwz: flow.Flow, nume: u32 = 0,
pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.rawd = try std.fs.path.join(allo, &.{ self.dirz, "raw" }); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.c1zz = cmok.Mock.init(allo); self.c2zz = cmok.Mock.init(allo); self.c3zz = cmok.Mock.init(allo); self.nume = 0; self.stos = .{ .{ .name = "b2zz", .store = self.c1zz.store(), .capb = BIGG }, .{ .name = "r2zz", .store = self.c2zz.store(), .capb = BIGG }, .{ .name = "tigr", .store = self.c3zz.store(), .capb = BIGG } }; self.sqls = .{ .{ .name = "turs", .sql2 = self.c1zz.sql2(), .capb = BIGG }, .{ .name = "neon", .sql2 = self.c2zz.sql2(), .capb = BIGG } }; self.flwz = .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .stos = &self.stos, .sqls = &self.sqls }; self.flwz.conf.clou_fail_runs = 1; }
pub fn down(self: *Rigg) void { self.c1zz.deinit(); self.c2zz.deinit(); self.c3zz.deinit(); self.aren.deinit(); self.dbzz.close(); allo.free(self.rawd); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn queu(self: *Rigg) !void { self.nume += 1; const bodz = try std.fmt.allocPrint(self.aren.allocator(), "flow body number {d}", .{self.nume}); const sav2 = try file.fileSave(allo, std.testing.io, self.rawd, bodz); const hexz = try self.aren.allocator().dupe(u8, &sav2.hexz); try outb.outbAddz(&self.dbzz, "file", hexz, 0, false); const urlz = try std.fmt.allocPrint(self.aren.allocator(), "http://f/{d}", .{self.nume}); try inde.pageSetz(&self.dbzz, urlz, .{ .hexz = hexz, .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = NOWZ, .next = 2 }); try inde.recoSetz(&self.dbzz, urlz, .{ .hexz = hexz, .kind = "text", .body = "b" }, NOWZ); try outb.outbAddz(&self.dbzz, "rec", urlz, 0, false); }
pub fn mkpk(self: *Rigg, mock: *cmok.Mock, name: []const u8) !void { const aren = self.aren.allocator(); self.nume += 1; const bodz = try std.fmt.allocPrint(aren, "old pack body number {d} {s}", .{ self.nume, "pad pad pad pad pad pad pad pad pad pad pad pad pad pad pad pad" }); const part: pack.Part = .{ .hexz = try aren.dupe(u8, &hash.hashHexz(bodz)), .gzzz = try file.gzipPack(aren, bodz) }; const byts = try pack.packBuil(aren, &.{part}); const ents = try pack.packPars(aren, byts); const stoz = mock.store(); try stoz.put(stoz.ctx2, aren, std.testing.io, name, byts); var insz = try self.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz,vfyz,vend) VALUES(?1,?2,?3,?4,1,'b2zz');"); defer insz.fini(); try insz.bindText(1, ents[0].hexz); try insz.bindText(2, name); try insz.bindIntz(3, @intCast(ents[0].offs)); try insz.bindIntz(4, @intCast(ents[0].lenz)); _ = try insz.step(); }
pub fn scal(self: *Rigg, sqlz: [:0]const u8) !i64 { var stmt = try self.dbzz.prep(sqlz); defer stmt.fini(); if (!try stmt.step()) return -1; return stmt.colzIntz(0); }
pub fn runzNumb(_: *Rigg, mock: *cmok.Mock) usize { var cont: usize = 0; var iter = mock.map.keyIterator(); while (iter.next()) |key2| { if (std.mem.startsWith(u8, key2.*, "runs/")) cont += 1; } return cont; } };
test "happy path: first healthy store and database, one try, phases ran, nothing remembered as failed" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.queu(); const fres = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqualStrings("b2zz", fres.stor); try std.testing.expectEqualStrings("turs", fres.sqlv); try std.testing.expectEqual(@as(u8, 1), fres.tris); try std.testing.expectEqual(@as(u32, 1), fres.sres.fil2); try std.testing.expectEqual(@as(u32, 1), fres.sres.recs); try std.testing.expectEqual(@as(usize, 1), rig3.runzNumb(&rig3.c1zz)); try std.testing.expectEqual(@as(usize, 0), rig3.runzNumb(&rig3.c2zz)); try std.testing.expect(fres.live.ranz); try std.testing.expect(fres.veri.ranz); try std.testing.expectEqual(@as(usize, 0), fres.alrt.len); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "b2zz", NOWZ)); }
test "store down: the next store takes over in the same run, the choice sticks for the next run" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.queu(); rig3.c1zz.stoo = true; const rsl1 = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqualStrings("r2zz", rsl1.stor); try std.testing.expectEqualStrings("turs", rsl1.sqlv); try std.testing.expectEqual(@as(u8, 2), rsl1.tris); try std.testing.expectEqual(@as(usize, 1), rig3.runzNumb(&rig3.c2zz)); try std.testing.expect(!try fail.failOkay(&rig3.dbzz, "b2zz", NOWZ + 1000)); rig3.c1zz.stoo = false; try rig3.queu(); const rsl2 = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ + 3600000 * 7); try std.testing.expectEqualStrings("r2zz", rsl2.stor); try std.testing.expectEqual(@as(u8, 1), rsl2.tris); try std.testing.expectEqual(@as(i64, 2), try rig3.scal("SELECT count(*) FROM pack WHERE vend='r2zz';")); }
test "database down: the next database takes over, records land there" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.queu(); rig3.c1zz.sqlo = true; const fres = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqualStrings("b2zz", fres.stor); try std.testing.expectEqualStrings("neon", fres.sqlv); try std.testing.expectEqual(@as(u8, 2), fres.tris); try std.testing.expect(rig3.c2zz.sawzStmt("INTO cl_page") >= 1); try std.testing.expect(!try fail.failOkay(&rig3.dbzz, "turs", NOWZ + 1000)); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "neon", NOWZ + 1000)); }
test "denied (blocked or suspended) vendors are skipped until the first of next month" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.queu(); rig3.c1zz.deny = true; const fres = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqualStrings("r2zz", fres.stor); try std.testing.expectEqualStrings("neon", fres.sqlv); try std.testing.expectEqual(@as(u8, 3), fres.tris); const nxtz = civi.civiNext(NOWZ); try std.testing.expectEqual(nxtz, try fail.failUnti(&rig3.dbzz, "b2zz")); try std.testing.expectEqual(nxtz, try fail.failUnti(&rig3.dbzz, "turs")); try std.testing.expect(try fail.failOkay(&rig3.dbzz, "b2zz", nxtz)); }
test "everything down: a typed error, nothing lost, every file is still queued" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.queu(); rig3.c1zz.offl = true; rig3.c2zz.offl = true; rig3.c3zz.offl = true; try std.testing.expectError(error.CloudDeny, flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ)); try std.testing.expectEqual(@as(i64, 2), try outb.outbCont(&rig3.dbzz, 0)); }
test "young alert: over the high mark with only young packs, an alert line and the vendor is skipped for new uploads" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for ([_][]const u8{ "runs/20261120T000000Z-a1.pack", "runs/20261121T000000Z-b2.pack", "runs/20261122T000000Z-c3.pack" }) |nam2| try rig3.mkpk(&rig3.c1zz, nam2); rig3.stos[0].capb = rig3.c1zz.used() * 100 / 95; const rsl1 = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expectEqual(@as(usize, 1), rsl1.alrt.len); try std.testing.expect(std.mem.indexOf(u8, rsl1.alrt[0], "younger than 90 days") != null); try std.testing.expect(!try fail.failOkay(&rig3.dbzz, "b2zz", NOWZ + 1000)); try rig3.queu(); const rsl2 = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ + 3600000 * 7); try std.testing.expectEqualStrings("r2zz", rsl2.stor); try std.testing.expectEqual(@as(u8, 1), rsl2.tris); }
test "phases add up: old packs purged on the right vendor, keepalive and verify ran, totals in the result" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for ([_][]const u8{ "runs/20260101T000000Z-a1.pack", "runs/20260102T000000Z-b2.pack", "runs/20260103T000000Z-c3.pack" }) |nam2| try rig3.mkpk(&rig3.c1zz, nam2); rig3.flwz.conf.purg_maxx_pctz = 100; rig3.stos[0].capb = rig3.c1zz.used() * 100 / 95; const fres = try flow.flowSync(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expect(fres.pac4 >= 1); try std.testing.expect(rig3.runzNumb(&rig3.c1zz) < 3); try std.testing.expect(fres.live.ranz); try std.testing.expectEqual(@as(usize, 0), fres.alrt.len); }
test "flowPurg dry run plans without writing: nothing deleted, nothing remembered" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for ([_][]const u8{ "runs/20260101T000000Z-a1.pack", "runs/20260102T000000Z-b2.pack", "runs/20260103T000000Z-c3.pack" }) |nam2| try rig3.mkpk(&rig3.c1zz, nam2); rig3.flwz.conf.purg_maxx_pctz = 100; rig3.stos[0].capb = rig3.c1zz.used() * 100 / 95; rig3.flwz.dryz = true; const fres = try flow.flowPurg(&rig3.flwz, rig3.aren.allocator(), NOWZ); try std.testing.expect(fres.pac4 >= 1); try std.testing.expectEqual(@as(usize, 3), rig3.runzNumb(&rig3.c1zz)); try std.testing.expectEqual(@as(i64, 0), try rig3.scal("SELECT count(*) FROM purg;")); try std.testing.expectEqual(@as(i64, 0), try rig3.scal("SELECT count(*) FROM fovr;")); try std.testing.expect(!fres.live.ranz); }
